    case "max-connections": o.maxConnections=int(n)
    case "max-connections-per-host": o.perHost=int(n)
    case "max-response-body-size": o.maxBody=int(n)
    case "exclude": o.excludes=append(o.excludes,value)
    case "include": o.includes=append(o.includes,value)
