func parseRobots(body []byte) []robotRule {
    groups:=[]robotGroup{}
    group:=robotGroup{}
    rulesStarted:=false
    flush:=func(){if len(group.agents)>0 {groups=append(groups,group)};group=robotGroup{};rulesStarted=false}
    text:=strings.TrimPrefix(string(body),"\ufeff")
    for _,line:=range strings.Split(strings.ReplaceAll(text,"\r","\n"),"\n") {
        line=strings.TrimSpace(strings.SplitN(line,"#",2)[0])
        if line=="" {continue}
        name,value,ok:=strings.Cut(line,":");if !ok{continue}
        name=strings.ToLower(strings.TrimSpace(name));value=strings.TrimSpace(value)
        if name=="user-agent" {
            if rulesStarted{flush()}
            group.agents=append(group.agents,strings.ToLower(value))
        } else if (name=="allow" || name=="disallow") && len(group.agents)>0 {
            rulesStarted=true
            if value==""{continue}
            suffix:=""
            if strings.HasSuffix(value,"$") {suffix="$";value=strings.TrimSuffix(value,"$")}
            pattern:="^"+strings.ReplaceAll(regexp.QuoteMeta(value),`\*`,".*")+suffix
            expression,e:=regexp.Compile(pattern)
            if e==nil {group.rules=append(group.rules,robotRule{expression:expression,length:len(value),allow:name=="allow"})}
        }
    }
    flush()
    best:=-1
    selected:=[]robotRule{}
    for _,g:=range groups {
        score:=-1
        for _,a:=range g.agents {
            if a=="*" && score<0 {score=0}
            if a!="" && a!="*" && strings.Contains("muffet",a) && len(a)>score {score=len(a)}
        }
        if score<0{continue}
        if score>best {best=score;selected=nil}
        if score==best{selected=append(selected,g.rules...)}
    }
    return selected
}
func parseSitemap(body []byte) (map[string]bool,error) {
    entries:=map[string]bool{}
    decoder:=xml.NewDecoder(bytes.NewReader(body))
    stack:=[]string{}
    var loc strings.Builder
    inLoc:=false
    for {
        token,err:=decoder.Token()
        if err==io.EOF{break}
        if err!=nil{return nil,err}
        switch t:=token.(type) {
        case xml.StartElement:
            stack=append(stack,t.Name.Local)
            if t.Name.Local=="loc" && len(stack)>=2 && stack[len(stack)-2]=="url" {
                inLoc=true;loc.Reset()
            }
        case xml.CharData:
            if inLoc{loc.Write([]byte(t))}
        case xml.EndElement:
            if t.Name.Local=="loc" && inLoc {entries[loc.String()]=true;inLoc=false}
            if len(stack)>0 {stack=stack[:len(stack)-1]}
        }
    }
    return entries,nil
