    c.wg.Add(1)
    c.mu.Unlock()
    go c.visit(page)
}
func (c *crawler) visit(page *fetchedPage) {
    defer c.wg.Done()
    doc:=page.document
    successes:=[]linkResult{}
    failures:=[]linkResult{}
    links:=map[string]bool{}
    for _,ref:=range doc.references {
        u,e:=url.Parse(ref)
        if e!=nil {
            if !links[ref] {failures=append(failures,linkResult{URL:ref,Error:e.Error()});links[ref]=true}
            continue
        }
        u=doc.base.ResolveReference(u)
        if u.Scheme!="http" && u.Scheme!="https" {continue}
        raw:=u.String()
        if !c.options.includesURL(raw) {continue}
        links[raw]=true
    }
    type completedLink struct {result linkResult;page *fetchedPage}
    done:=make(chan completedLink,len(links))
    pending:=0
    invalid:=map[string]bool{}
    for _,r:=range failures {invalid[r.URL]=true}
    for raw:=range links {
        if invalid[raw] {continue}
        pending++
        go func(raw string){
            found,e:=c.fetcher.fetch(raw)
            r:=linkResult{URL:raw}
            if e!=nil {r.Error=e.Error()} else {r.Status=found.status}
            done<-completedLink{r,found}
        }(raw)
    }
    for i:=0;i<pending;i++ {
        link:=<-done
        if link.result.Error!="" {failures=append(failures,link.result)} else {
            successes=append(successes,link.result)
            found:=link.page
            if !c.options.onePage && found.document!=nil && found.url.Hostname()==c.hostname && c.policy.allowed(found.url) {
                c.schedule(found)
            }
        }
    }
    c.results<-pageResult{URL:page.url.String(),Links:append(successes,failures...)}
}
func (c *crawler) run(root *fetchedPage) <-chan pageResult {
    c.schedule(root)
    go func(){c.wg.Wait();close(c.results)}()
    return c.results
}
