func terminal(fd uintptr) bool {
    var termios syscall.Termios
    _,_,err:=syscall.Syscall6(syscall.SYS_IOCTL,fd,syscall.TCGETS,uintptr(unsafe.Pointer(&termios)),0,0,0)
    return err==0
}
func colorEnabled(o *options) bool {
    if o.color=="always" {return true}
    if o.color=="never" {return false}
    if _,ok:=os.LookupEnv("NO_COLOR");ok{return false}
    return os.Getenv("TERM")!="dumb" && terminal(os.Stdout.Fd())
}
func resultLabel(r linkResult) string {
    if r.Error!="" {return r.Error}
    return strconv.Itoa(r.Status)
}
func printText(result pageResult, o *options) {
    visible:=make([]linkResult,0,len(result.Links))
    for _,r:=range result.Links {if o.verbose || r.Error!="" {visible=append(visible,r)}}
    if len(visible)==0 && !o.verbose{return}
    sort.SliceStable(visible,func(i,j int)bool{
        a,b:=visible[i],visible[j]
        if (a.Error=="")!=(b.Error==""){return a.Error==""}
        la,lb:=resultLabel(a),resultLabel(b)
        if la!=lb{return la<lb}
        return a.URL<b.URL
    })
    color:=colorEnabled(o)
    if color {fmt.Printf("\x1b[33m%s\x1b[0m\n",result.URL)} else {fmt.Println(result.URL)}
    for _,r:=range visible {
        label:=resultLabel(r)
        if color {
            c:=32;if r.Error!=""{c=31}
            fmt.Printf("\t\x1b[%dm%s\x1b[0m\t%s\n",c,label,r.URL)
        } else {fmt.Printf("\t%s\t%s\n",label,r.URL)}
