func TestOptionParser(t *testing.T) {
    tests:=[]struct{args []string;err string}{
        {[]string{"--bogus"},"unknown flag `bogus'"},
        {[]string{"--verbose=false"},"bool flag `-v, --verbose' cannot have an argument"},
        {[]string{"--timeout"},"expected argument for flag `-t, --timeout'"},
        {[]string{"--timeout","--help"},"expected argument for flag `-t, --timeout', but got option `--help'"},
        {[]string{"-c","--"},"expected argument for flag `-c, --max-connections', but got double dash `--'"},
        {[]string{"-vt1"},"expected argument for flag `-t, --timeout'"},
        {[]string{"--format=xml"},"Invalid value `xml' for option `--format'. Allowed values are: text, json or junit"},
        {[]string{"--max-retries=-1"},"invalid argument for flag `--max-retries' (expected uint): strconv.ParseUint: parsing \"-1\": invalid syntax"},
        {[]string{"--exclude","-1"},"expected argument for flag `-e, --exclude', but got option `-1'"},
        {[]string{"--=x"},"unknown flag `'"},
        {[]string{"-é"},"unknown flag `é'"},
    }
    for _,test:=range tests {
        _,_,err:=parseOptions(test.args)
        if err==nil || err.Error()!=test.err {t.Errorf("%q: got %v; want %s",test.args,err,test.err)}
    }
    o,args,err:=parseOptions([]string{"-vft","2","-c0x10","-e=skip","--header=X-Test: first","--","--url"})
    if err!=nil {t.Fatal(err)}
    if !o.verbose || !o.ignoreFragments || o.timeout!=2 || o.maxConnections!=16 || len(args)!=1 || args[0]!="--url" {t.Fatalf("unexpected options: %+v, %q",o,args)}
}
func TestPreparedOptions(t *testing.T) {
    o,_,err:=parseOptions([]string{"--accepted-status-codes=200..300,403","--include=example","--exclude=skip","--header=x-key: first","--header=X-Key: second"})
    if err!=nil {t.Fatal(err)}
    if err=o.prepare();err!=nil {t.Fatal(err)}
    if !o.accepts(200) || !o.accepts(299) || o.accepts(300) || !o.accepts(403) {t.Fatal("status ranges should be half open")}
    if o.headers["X-Key"]!="first" {t.Fatalf("wrong duplicate header: %v",o.headers)}
    if !o.includesURL("http://example/") || o.includesURL("http://else/") || o.includesURL("http://example/skip") {t.Fatal("incorrect URL filters")}
    o,_,_=parseOptions([]string{"--format=junit","--json","--experimental-verbose-json"})
    if err=o.prepare();err!=nil {t.Fatal(err)}
    if o.format!="json" || !o.verbose {t.Fatalf("legacy options: %+v",o)}
    o,_,_=parseOptions([]string{"--format=junit","--verbose"})
    if err=o.prepare();err==nil || !strings.Contains(err.Error(),"verbose option not supported") {t.Fatalf("expected JUnit validation, got %v",err)}
}
