package main

import (
    "bytes"
    "compress/gzip"
    "fmt"
    "net/http"
    "net/http/httptest"
    "net/url"
    "sort"
    "strings"
    "sync"
    "testing"
)

func testOptions(t *testing.T) options {
    t.Helper();o:=defaultOptions()
    if err:=o.prepare();err!=nil {t.Fatal(err)}
    return o
}
func TestFetcherRedirectsFragmentsAndCache(t *testing.T) {
    var mu sync.Mutex
    counts:=map[string]int{}
    server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
        mu.Lock();counts[r.URL.Path]++;mu.Unlock()
        if r.Method!="GET" || r.Header.Get("Accept")!="*/*" || r.Header.Get("User-Agent")!="" {t.Errorf("unexpected request: %s %v",r.Method,r.Header)}
        w.Header().Set("Content-Type","text/html")
        if r.URL.Path=="/r" {w.Header().Set("Location","/page#ignored");w.WriteHeader(302);return}
        fmt.Fprint(w,`<div id="present"></div><a href="/next">n</a>`)
    }))
    defer server.Close()
    o:=testOptions(t);f:=newFetcher(&o)
    page,err:=f.fetch(server.URL+"/r#present")
    if err!=nil {t.Fatal(err)}
    if page.url.String()!=server.URL+"/page" {t.Fatalf("redirect target: %s",page.url)}
    if _,err=f.fetch(server.URL+"/r#absent");err==nil || err.Error()!="id #absent not found" {t.Fatalf("fragment error: %v",err)}
    if _,err=f.fetch(server.URL+"/r");err!=nil {t.Fatal(err)}
    mu.Lock();defer mu.Unlock()
    if counts["/r"]!=1 || counts["/page"]!=1 {t.Fatalf("cache: %v",counts)}
}
func TestCrawlerGraph(t *testing.T) {
    server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
        w.Header().Set("Content-Type","text/html")
        switch r.URL.Path {
        case "/":fmt.Fprint(w,`<a href="/page">p</a><a href="/bad">b</a><a href="/bad">duplicate</a><a href="/other#absent">o</a><a href="mailto:a@b">m</a>`)
        case "/page":fmt.Fprint(w,`<a href="/">back</a><a href="/empty">e</a>`)
        case "/other":fmt.Fprint(w,`<a href="/must-not-crawl">hidden</a>`)
        case "/empty":
        default:w.WriteHeader(404)
        }
    }))
    defer server.Close()
    o:=testOptions(t);f:=newFetcher(&o)
    root,err:=f.fetch(server.URL+"/");if err!=nil {t.Fatal(err)}
    c:=newCrawler(&o,f,root,crawlPolicy{})
    pages:=map[string]pageResult{}
    for p:=range c.run(root) {pages[p.URL]=p}
    if len(pages)!=3 {t.Fatalf("pages: %v",pages)}
    rp:=pages[server.URL+"/"]
    if len(rp.Links)!=3 {t.Fatalf("deduplication: %v",rp.Links)}
    failures:=[]string{}
    for _,link:=range rp.Links {if link.Error!="" {failures=append(failures,link.Error)}}
    sort.Strings(failures)
    if strings.Join(failures,",")!="404,id #absent not found" {t.Fatalf("failures: %v",failures)}
}
func TestResponseDecodingAndSizeLimit(t *testing.T) {
    var compressed bytes.Buffer
    z:=gzip.NewWriter(&compressed);z.Write([]byte(`<a href="/target">x</a>`));z.Close()
    server:=httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
        w.Header().Set("Content-Type","text/html")
        switch r.URL.Path {
        case "/gzip":w.Header().Set("Content-Encoding","gzip");w.Write(compressed.Bytes())
        case "/mime":w.Header().Set("Content-Type","text/html; invalid");w.Header().Set("Content-Encoding","gzip");fmt.Fprint(w,"bad gzip")
        case "/large":fmt.Fprint(w,strings.Repeat("a",1000))
        }
    }))
    defer server.Close()
    o:=testOptions(t);o.maxBody=100;f:=newFetcher(&o)
    p,err:=f.fetch(server.URL+"/gzip")
    if err!=nil || len(p.document.references)!=1 {t.Fatalf("gzip: %v %v",p,err)}
    _,err=f.fetch(server.URL+"/mime")
    if err==nil || err.Error()!="mime: invalid media parameter" {t.Fatalf("media error precedence: %v",err)}
    _,err=f.fetch(server.URL+"/large")
    if err==nil || err.Error()!="body size exceeds the given limit" {t.Fatalf("body limit: %v",err)}
}
func TestCrawlPolicies(t *testing.T) {
    p:=crawlPolicy{rules:parseRobots([]byte("User-agent: *\nDisallow: /\nUser-agent: Muffet\nDisallow: /private\nAllow: /private/open\n"))}
    for path,want:=range map[string]bool{"/":true,"/private/a":false,"/private/open/file":true} {
