package main

import (
    "io"
    "os"
    "strings"
    "testing"
)
func captureOutput(t *testing.T,fn func()) string {
    t.Helper()
    r,w,err:=os.Pipe();if err!=nil {t.Fatal(err)}
    old:=os.Stdout;os.Stdout=w
    defer func(){os.Stdout=old}()
    fn();w.Close()
    data,err:=io.ReadAll(r);r.Close();if err!=nil {t.Fatal(err)}
    return string(data)
}
func TestTextResultOrdering(t *testing.T) {
    o:=defaultOptions();o.verbose=true;o.color="never"
    result:=pageResult{URL:"http://site/",Links:[]linkResult{
        {URL:"http://site/z",Error:"404"},{URL:"http://site/a",Error:"201"},
        {URL:"http://site/a",Status:404},{URL:"http://site/b",Status:200},
    }}
    got:=captureOutput(t,func(){printText(result,&o)})
    want:="http://site/\n\t200\thttp://site/b\n\t404\thttp://site/a\n\t201\thttp://site/a\n\t404\thttp://site/z\n"
    if got!=want {t.Fatalf("got %q, want %q",got,want)}
}
func TestReports(t *testing.T) {
    result:=pageResult{URL:"http://site/",Links:[]linkResult{{URL:"http://site/good",Status:200},{URL:"http://site/bad?a=1&b=2",Error:"404"}}}
    for _,format:=range []string{"json","junit"} {
        o:=defaultOptions();o.format=format
        ch:=make(chan pageResult,1);ch<-result;close(ch)
        code:=0
        out:=captureOutput(t,func(){code=report(ch,&o)})
        if code!=1 {t.Fatalf("exit status: %d",code)}
        if format=="json" {
            want:="[{\"url\":\"http://site/\",\"links\":[{\"url\":\"http://site/bad?a=1\\u0026b=2\",\"error\":\"404\"}]}]\n"
            if out!=want {t.Fatalf("JSON: %q",out)}
        } else {
            if !strings.HasPrefix(out,"<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n") || !strings.Contains(out,`tests="2" failures="1" skipped="0"`) || !strings.Contains(out,`<failure message="404"></failure>`) {t.Fatalf("JUnit: %s",out)}
        }
    }
}
